def output_mapping(result):
    conflicting_events = []
    for event in result.event_blocks:
        conflicting_events.append(f"Event: {event.get('event_name', 'busy')}, Start: {event.get('start_time')}, End: {event.get('end_time')}")
    availability = len(result.event_blocks) == 0
    return {'availability': availability, 'conflictingEvents': '\n'.join(conflicting_events)}

